import {
    Scene,
    Color,
    Camera2DController,
    Rect,
    Path,
    Arrow,
    createAnim,
    boilAnim,
} from "retiam";

export class ExcalidrawOverviewScene extends Scene {
    public override async run(): Promise<void> {
        new Camera2DController(this, this.camera, { zoom: 12 });
        this.clearColor(Color.fromHex("#ffffff"));

        // 1. Hand-drawn card with cross-hatch fill
        const card = new Rect(4.0, 4.0).toExcalidraw({
            strokeColor: Color.fromHex("#141414"),
            strokeWidth: 0.08,
            fillStyle: 'cross-hatch',
            fillColor: Color.fromHex("#93c5fd"),
            fillLineColor: Color.fromHex("#1a73e8"),
            fillGap: 0.15,
            passes: 2,
        });
        card.transform.position.set([-2.5, 0, 0]);

        // 2. Diamond node with solid fill
        const diamond = new Path("M 0 1.25 L 1.25 0 L 0 -1.25 L -1.25 0 Z").toExcalidraw({
            strokeColor: Color.fromHex("#141414"),
            fillStyle: 'filled',
            fillColor: Color.fromHex("#fd7e14"),
        });
        diamond.transform.position.set([2.5, 0, 0]);

        // 3. Hand-drawn connector arrow
        const arrow = new Arrow([-0.5, 0, 0], [1.2, 0, 0]).toExcalidraw({
            strokeColor: Color.fromHex("#141414"),
            strokeWidth: 0.08,
            anchorEnds: true,
        });

        // Concurrently draw and boil the card
        await this.play(createAnim(card), card.boil({ duration: 1000 }));

        // Introduce diamond and arrow
        await this.play(createAnim(diamond), createAnim(arrow));

        // Boil all shapes together for 3 seconds
        await this.play(boilAnim([card, diamond, arrow], { duration: 3000, speed: 1.0 }));
    }
}
